python3 << 'PY'
import os, re, collections

root = "/bench/repo"
internal = os.path.join(root, "internal")

# Collect all go files
def go_files(base, include_tests=True):
    out = []
    for dirpath, _, files in os.walk(base):
        if "/.git" in dirpath or "/web/node_modules" in dirpath or "/proto/gen" in dirpath:
            continue
        for f in files:
            if f.endswith(".go"):
                if not include_tests and f.endswith("_test.go"):
                    continue
                out.append(os.path.join(dirpath, f))
    return out

# Parse package name and declarations from internal (non-test)
decl_re = re.compile(r'^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(')

decls = []  # (pkg, recv, name, path, line, exported)
pkg_of_file = {}

for path in go_files(internal, include_tests=False):
    with open(path) as fh:
        text = fh.read()
    m = re.search(r'^package\s+(\w+)', text, re.M)
    if not m:
        continue
    pkg = m.group(1)
    pkg_of_file[path] = pkg
    for i, line in enumerate(text.splitlines(), 1):
        dm = decl_re.match(line)
        if not dm:
            continue
        recv, name = dm.group(1), dm.group(2)
        if name in ("init",):
            continue
        decls.append({
            "pkg": pkg,
            "recv": recv,
            "name": name,
            "path": path,
            "line": i,
            "exported": name[0].isupper(),
        })

print(f"Declarations (non-test internal): {len(decls)}")
print(f"Exported: {sum(1 for d in decls if d['exported'])}")

# Read all backend go files for searching
all_files = []
for base in [os.path.join(root, p) for p in ["internal", "server", "store", "cmd"]]:
    all_files.extend(go_files(base, include_tests=True))

file_contents = {}
file_pkg = {}
for path in all_files:
    with open(path) as fh:
        file_contents[path] = fh.read()
    m = re.search(r'^package\s+(\w+)', file_contents[path], re.M)
    file_pkg[path] = m.group(1) if m else ""

# For exported package-level functions, count pkg.Name( and same-pkg Name(
# For methods, count .Name( more carefully

def count_calls(d, exclude_tests=False):
    name = d["name"]
    pkg = d["pkg"]
    is_method = d["recv"] is not None
    sites = []
    # pattern
    if is_method:
        # method call: .Name(  not the declaration
        pat = re.compile(r'\.' + re.escape(name) + r'\s*\(')
    else:
        # pkg.Name( or Name( in same package
        pat_qual = re.compile(r'\b' + re.escape(pkg) + r'\.' + re.escape(name) + r'\s*\(')
        pat_local = re.compile(r'(?<!\.)\b' + re.escape(name) + r'\s*\(')

    for path, text in file_contents.items():
        if exclude_tests and path.endswith("_test.go"):
            continue
        lines = text.splitlines()
        for i, line in enumerate(lines, 1):
            # skip the declaration itself
            if path == d["path"] and i == d["line"]:
                continue
            # skip other declarations of same name
            if decl_re.match(line) and re.search(r'\b' + re.escape(name) + r'\s*\(', line):
                continue
            if is_method:
                if pat.search(line):
                    sites.append((path, i, line.strip()[:120]))
            else:
                if pat_qual.search(line):
                    sites.append((path, i, line.strip()[:120]))
                elif file_pkg.get(path) == pkg and pat_local.search(line):
                    sites.append((path, i, line.strip()[:120]))
    return sites

# First pass: exported functions only (more reliable)
results = []
for d in decls:
    if not d["exported"]:
        continue
    sites = count_calls(d, exclude_tests=False)
    results.append((len(sites), d, sites))

results.sort(key=lambda x: -x[0])
print("\n=== TOP exported (all files incl tests) ===")
for n, d, sites in results[:25]:
    recv = f"({d['recv']}) " if d['recv'] else ""
    print(f"{n:4d}  {d['pkg']}.{recv}{d['name']}  {d['path'].replace('/bench/repo/','')}:{d['line']}")

print("\n=== TOP exported (non-test only) ===")
results2 = []
for d in decls:
    if not d["exported"]:
        continue
    sites = count_calls(d, exclude_tests=True)
    results2.append((len(sites), d))
results2.sort(key=lambda x: -x[0])
for n, d in results2[:15]:
    recv = f"({d['recv']}) " if d['recv'] else ""
    print(f"{n:4d}  {d['pkg']}.{recv}{d['name']}  {d['path'].replace('/bench/repo/','')}:{d['line']}")
