perl -e '
use strict;
use warnings;
use File::Find;

my $root = "/bench/repo";
my $internal = "$root/internal";

sub collect_go {
  my ($base, $include_tests) = @_;
  my @files;
  find({
    wanted => sub {
      return unless /\.go$/;
      return if !$include_tests && /_test\.go$/;
      my $p = $File::Find::name;
      return if $p =~ m{/\.git/} || $p =~ m{/web/node_modules/} || $p =~ m{/proto/gen/};
      push @files, $p;
    },
    no_chdir => 1,
  }, $base);
  return @files;
}

my @internal_files = collect_go($internal, 0);
my @decls; # hashrefs

sub read_file {
  my ($p) = @_;
  open my $fh, "<", $p or die $!;
  local $/;
  return <$fh>;
}

for my $path (@internal_files) {
  my $text = read_file($path);
  my ($pkg) = $text =~ /^package\s+(\w+)/m;
  next unless $pkg;
  my $line_no = 0;
  for my $line (split /\n/, $text) {
    $line_no++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      next if $name eq "init";
      push @decls, {
        pkg => $pkg, recv => $recv, name => $name, path => $path, line => $line_no,
        exported => ($name =~ /^[A-Z]/) ? 1 : 0,
      };
    }
  }
}

print "Declarations: " . scalar(@decls) . "\n";
print "Exported: " . (scalar grep { $_->{exported} } @decls) . "\n";

my @all_files;
for my $base (qw(internal server store cmd)) {
  push @all_files, collect_go("$root/$base", 1);
}

my %contents;
my %file_pkg;
for my $path (@all_files) {
  my $text = read_file($path);
  $contents{$path} = $text;
  my ($pkg) = $text =~ /^package\s+(\w+)/m;
  $file_pkg{$path} = $pkg // "";
}

sub count_calls {
  my ($d, $exclude_tests) = @_;
  my $name = $d->{name};
  my $pkg = $d->{pkg};
  my $is_method = defined $d->{recv};
  my $count = 0;
  for my $path (keys %contents) {
    next if $exclude_tests && $path =~ /_test\.go$/;
    my $text = $contents{$path};
    my $i = 0;
    for my $line (split /\n/, $text) {
      $i++;
      next if $path eq $d->{path} && $i == $d->{line};
      next if $line =~ /^func\s+/ && $line =~ /\b\Q$name\E\s*\(/;
      if ($is_method) {
        if ($line =~ /\.\Q$name\E\s*\(/) { $count++; }
