      }
      push @sites, sprintf("%s:%d: %s", $path, $i, substr($line,0,140)) if $hit;
    }
  }
  return @sites;
}

# Rank unique-named symbols (name appears once in internal decls) - more reliable
my @unique;
for my $d (@decls) {
  next unless $namecount{$d->{name}} == 1;
  my @sites = count_and_sites($d, 0);
  push @unique, [scalar(@sites), $d, \@sites];
}
@unique = sort { $b->[0] <=> $a->[0] } @unique;

print "=== TOP unique-named symbols (incl tests) ===\n";
for my $i (0..20) {
  last if $i > $#unique;
  my ($n, $d) = @{$unique[$i]};
  my $recv = $d->{recv} ? "($d->{recv}) " : "";
  my $p = $d->{path}; $p =~ s{^/bench/repo/}{};
  print sprintf("%4d  %s.%s%s  %s:%d  exported=%d method=%d\n", $n, $d->{pkg}, $recv, $d->{name}, $p, $d->{line}, $d->{exported}, $d->{is_method});
}

# Also package-level only (all names)
print "\n=== TOP package-level functions (incl tests) ===\n";
my @funcs;
for my $d (@decls) {
  next if $d->{is_method};
  my @sites = count_and_sites($d, 0);
  push @funcs, [scalar(@sites), $d];
}
@funcs = sort { $b->[0] <=> $a->[0] } @funcs;
for my $i (0..20) {
  last if $i > $#funcs;
  my ($n, $d) = @{$funcs[$i]};
  my $p = $d->{path}; $p =~ s{^/bench/repo/}{};
  print sprintf("%4d  %s.%s  %s:%d exported=%d\n", $n, $d->{pkg}, $d->{name}, $p, $d->{line}, $d->{exported});
}
'

