perl -e '
use strict;
use warnings;

my @entities = qw(
  Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation MemoShare
  Reaction User UserIdentity UserSetting
);

# also common related but not entities: skip Find*/Update*/Delete*

# collect go files outside store/
open my $af, "<", "/tmp/all_go.txt" or do {
  # rebuild
  @ARGV = ();
};
my @files;
open my $cmd, "-|", "find /bench/repo/server /bench/repo/cmd /bench/repo/internal -name \"*.go\"" or die $!;
while (<$cmd>) { chomp; push @files, $_; }
close $cmd;

sub pkg_of {
  my ($path) = @_;
  # derive import path suffix from dir
  my $dir = $path;
  $dir =~ s{/[^/]+$}{};
  $dir =~ s{^/bench/repo/}{};
  return $dir;
}

my %counts; # entity -> {pkg -> count}
my %sites;

for my $path (@files) {
  open my $fh, "<", $path or die $!;
  my $text = do { local $/; <$fh> };
  close $fh;
  next unless $text =~ /\"github.com\/usememos\/memos\/store\"/;
  my $pkg = pkg_of($path);
  for my $ent (@entities) {
    # store.Ent as a type/value reference, not store.FindEnt etc.
    my $n = 0;
    while ($text =~ /\bstore\.$ent\b/g) {
      my $before = substr($text, 0, $-[0]);
      # exclude FindX, UpdateX, DeleteX, CreateX if those were prefixes - we used exact Ent
      $n++;
    }
    if ($n) {
      $counts{$ent}{$pkg} += $n;
    }
  }
}

print "Packages per entity (outside store/):\n";
my @ranked = sort { scalar(keys %{$counts{$b}}) <=> scalar(keys %{$counts{$a}}) || $a cmp $b } @entities;
for my $ent (@ranked) {
  my @pkgs = sort keys %{$counts{$ent}};
  printf "%2d pkgs  %-20s  %s\n", scalar(@pkgs), $ent, join(", ", @pkgs);
}
'

